// The window's end, then the self-check
static __attribute__((noinline)) int forge_check(uint32_t t0) {
    uint32_t cycles = snrt_mcycle() - t0;
#ifdef FORGE_QUIET
    write_csr(0x7c5, 7);  // check
    (void)cycles;
#endif  // FORGE_QUIET
#ifndef FORGE_QUIET
    printf("forge cycles: %u\n", cycles);
#endif  // FORGE_QUIET
    int err = 0;
    int data_errors = 0;
    for (uint32_t i = 0; i < 16; i++) {
        if (((volatile int64_t *)q)[i] != q_golden[i]) {
            data_errors++;
        }
    }
    err += data_errors;
#ifndef FORGE_QUIET
    printf("forge data: %d errors (%u words)\n", data_errors, 16u);
#endif  // FORGE_QUIET
#ifndef FORGE_QUIET
    printf("forge counter mult_matvec: %u\n", forge_counter[0]);
#endif  // FORGE_QUIET
    err += forge_counter[0] < 2048;
#ifndef FORGE_QUIET
    printf("forge errors: %d\n", err);
#endif  // FORGE_QUIET
    return err;
}

// Each core's function, by snrt_cluster_core_idx()
static int (*const forge_cores[1])(void) = {forge_core_0};

int main() {
    uint32_t t0 = snrt_mcycle();
    uint32_t core = snrt_cluster_core_idx();
    int err = forge_cores[core]();
    if (core == 0) {
        err += forge_check(t0);
    }
    return err;
}
